package com.example.english_app;
import android.os.Bundle;import android.widget.EditText;public class WritingActivity extends LearningBaseActivity {@Override protected int layout(){return R.layout.activity_writing;}@Override public void onCreate(Bundle b){super.onCreate(b);findViewById(R.id.submit).setOnClickListener(v->{String[] s=new String[3];for(int i=0;i<3;i++){s[i]=((EditText)findViewById(getResources().getIdentifier("sentence"+(i+1),"id",getPackageName()))).getText().toString().trim();if(s[i].split("\\s+").length<3){message(R.id.warning,"Câu "+(i+1)+" cần ít nhất 3 từ. Vui lòng viết đầy đủ.");StateScreensActivity.open(this,"writing_validation");return;}for(int j=0;j<i;j++)if(s[i].equalsIgnoreCase(s[j])){message(R.id.warning,"Các câu không được giống hệt nhau.");StateScreensActivity.open(this,"writing_validation");return;}}go(LessonCompleteActivity.class);});}}
